import sys
from collections import Counter

def countStrings(S):
    n = len(S)
    last = [-1] * 26
    swaps = set()

    for i in range(n - 1, -1, -1):
        for j in range(last[S[i] - ord('a')]):
            swaps.add((S[i], S[j]))
        last[S[i] - ord('a')] = i

    return len(swaps)

input = sys.stdin.read().strip()
print(countStrings(input))
